using Avalonia.Controls;
using SalekhPos.Desktop.Application.Management;
namespace SalekhPos.Desktop; public sealed partial class ManagerPlatformWindow : Window { private readonly IFeatureManager features; private readonly IFiscalizationManager fiscalization; private readonly IIntegrationManager integrations; private readonly IBillingManager billing; private readonly ISubscriptionManager subscriptions; private readonly Guid organizationId; private readonly Guid branchId; public ManagerPlatformWindow() => throw new InvalidOperationException("Platform runtime is required."); public ManagerPlatformWindow(IFeatureManager features, IFiscalizationManager fiscalization, IIntegrationManager integrations, IBillingManager billing, ISubscriptionManager subscriptions, Guid organizationId, Guid branchId) { this.features = features; this.fiscalization = fiscalization; this.integrations = integrations; this.billing = billing; this.subscriptions = subscriptions; this.organizationId = organizationId; this.branchId = branchId; InitializeComponent(); ScopeText.Text = $"Organization {organizationId:D} · Branch {branchId:D}"; } private void FeaturesClick(object? s, Avalonia.Interactivity.RoutedEventArgs e) => new ManagerFeatureManagementWindow(features, organizationId).Show(this); private void FiscalizationClick(object? s, Avalonia.Interactivity.RoutedEventArgs e) => new ManagerFiscalizationWindow(fiscalization, organizationId, branchId).Show(this); private void IntegrationsClick(object? s, Avalonia.Interactivity.RoutedEventArgs e) => new ManagerIntegrationsWindow(integrations, organizationId).Show(this); private void BillingClick(object? s, Avalonia.Interactivity.RoutedEventArgs e) => new ManagerBillingWindow(billing, organizationId).Show(this); private void SubscriptionsClick(object? s, Avalonia.Interactivity.RoutedEventArgs e) => new ManagerSubscriptionsWindow(subscriptions, organizationId).Show(this); }
